-- TEST only. All fixtures are synthetic and rolled back; no mail or push is sent.
begin;
create temp table join_probe as select gen_random_uuid() c,gen_random_uuid() other_c,gen_random_uuid() team,gen_random_uuid() other_team,
 gen_random_uuid() admin_id,gen_random_uuid() parent_id,gen_random_uuid() trusted_id,gen_random_uuid() outsider_id,gen_random_uuid() unconfirmed_id,gen_random_uuid() season_id,gen_random_uuid() team_season_id;
grant select on join_probe to authenticated;
insert into public.clubs(id,name,status) select c,'Synthetic self join','active' from join_probe union all select other_c,'Synthetic other club','active' from join_probe;
insert into public.teams(id,club_id,name,age_group) select team,c,'U12 Test','U12' from join_probe union all select other_team,other_c,'U13 Other','U13' from join_probe;
insert into public.seasons(id,name) select season_id,'2098/99 self-join test' from join_probe;
insert into public.team_seasons(id,team_id,season_id,status) select team_season_id,team,season_id,'active' from join_probe;
insert into auth.users(id,email,email_confirmed_at) select u,u::text||'@self-join.invalid',case when u=unconfirmed_id then null else now() end from join_probe,lateral unnest(array[admin_id,parent_id,trusted_id,outsider_id,unconfirmed_id])u;
insert into public.user_roles(user_id,role) select admin_id,'admin' from join_probe;
insert into public.memberships(user_id,team_season_id,role) select trusted_id,team_season_id,'parent'::public.membership_role from join_probe;
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAILED: %',label;end if;end$$;
select set_config('request.jwt.claim.sub',admin_id::text,true) from join_probe;
set local role authenticated;
create temp table join_token as select public.exchange_invitation(c)->>'token' token from join_probe;
select pg_temp.check(not has_function_privilege('anon','public.exchange_join(uuid,text,boolean,uuid[])','execute'),'anonymous cannot join');
select pg_temp.check(not has_table_privilege('authenticated','private.exchange_member_teams','insert'),'no direct team writes');
select set_config('request.jwt.claim.sub',parent_id::text,true) from join_probe;
select pg_temp.check(jsonb_array_length(public.exchange_team_options(c,(select token from join_token)))=1,'only own club teams returned without needing children') from join_probe;
do $$declare p join_probe; t text;begin select * into p from join_probe; select token into t from join_token;
 begin perform public.exchange_join(p.c,t,true,array[]::uuid[]);raise exception 'EMPTY ACCEPTED';exception when raise_exception then if sqlerrm='EMPTY ACCEPTED' then raise;end if;end;
 begin perform public.exchange_join(p.c,t,true,array[p.other_team]);raise exception 'FOREIGN ACCEPTED';exception when raise_exception then if sqlerrm='FOREIGN ACCEPTED' then raise;end if;end;
 begin perform public.exchange_join(p.c,t,false,array[p.team]);raise exception 'NO CONSENT ACCEPTED';exception when raise_exception then if sqlerrm='NO CONSENT ACCEPTED' then raise;end if;end;
 begin perform public.exchange_join(p.c,repeat('0',64),true,array[p.team]);raise exception 'INVALID TOKEN ACCEPTED';exception when raise_exception then if sqlerrm='INVALID TOKEN ACCEPTED' then raise;end if;end;
 begin perform public.exchange_team_options(p.other_c,t);raise exception 'FOREIGN OPTIONS ACCEPTED';exception when raise_exception then if sqlerrm='FOREIGN OPTIONS ACCEPTED' then raise;end if;end;
 begin perform public.exchange_members_list(p.c);raise exception 'MEMBER LIST LEAK';exception when raise_exception then if sqlerrm='MEMBER LIST LEAK' then raise;end if;end;
 begin perform public.exchange_revoke(p.c,p.trusted_id);raise exception 'NONADMIN REVOKE';exception when raise_exception then if sqlerrm='NONADMIN REVOKE' then raise;end if;end;
 begin perform public.exchange_restore(p.c,p.trusted_id);raise exception 'NONADMIN RESTORE';exception when raise_exception then if sqlerrm='NONADMIN RESTORE' then raise;end if;end;
end $$;
select set_config('request.jwt.claim.sub',unconfirmed_id::text,true) from join_probe;
do $$begin begin perform public.exchange_join(c,(select token from join_token),true,array[team]) from join_probe;raise exception 'UNCONFIRMED ACCEPTED';exception when raise_exception then if sqlerrm='UNCONFIRMED ACCEPTED' then raise;end if;end;end $$;
select set_config('request.jwt.claim.sub',parent_id::text,true) from join_probe;
select pg_temp.check(public.exchange_join(c,(select token from join_token),true,array[team,team]),'join succeeds') from join_probe;
select pg_temp.check(public.exchange_join(c,(select token from join_token),true,array[team]),'join is repeatable') from join_probe;
select pg_temp.check(public.exchange_access(c),'new parent immediately enters') from join_probe;
select pg_temp.check((public.exchange_my_clubs()->0->'team_labels') ? 'U12','self-selected team used for listing labels');
insert into public.exchange_listings(club_id,title,category,size,condition,offer,status) select c,'Synthetic joined draft','Pulli','140','Gut','Gratis','Entwurf' from join_probe;
select pg_temp.check((select count(*)=1 from public.exchange_listings where title='Synthetic joined draft'),'joined parent can create draft');
select set_config('request.jwt.claim.sub',trusted_id::text,true) from join_probe;
select pg_temp.check(public.exchange_access(c),'existing app parent still enters') from join_probe;
select set_config('request.jwt.claim.sub',admin_id::text,true) from join_probe;
select pg_temp.check(jsonb_array_length(public.exchange_members_list(c))=2,'admin sees invited and existing app parents') from join_probe;
do $$begin begin perform public.exchange_revoke(c,admin_id) from join_probe;raise exception 'SELF LOCK';exception when raise_exception then if sqlerrm='SELF LOCK' then raise;end if;end;end $$;
select public.exchange_revoke(c,parent_id),public.exchange_revoke(c,trusted_id) from join_probe;
select set_config('request.jwt.claim.sub',parent_id::text,true) from join_probe;
select pg_temp.check(not public.exchange_access(c),'invited parent suspended') from join_probe;
select pg_temp.check((select count(*)=0 from public.exchange_listings where title='Synthetic joined draft'),'suspended cannot read internal draft');
do $$begin begin perform public.exchange_join(c,(select token from join_token),true,array[team]) from join_probe;raise exception 'SUSPENSION BYPASS';exception when raise_exception then if sqlerrm='SUSPENSION BYPASS' then raise;end if;end;end $$;
select set_config('request.jwt.claim.sub',trusted_id::text,true) from join_probe;
select pg_temp.check(not public.exchange_access(c),'suspension overrides existing app membership') from join_probe;
reset role;
select pg_temp.check((select count(*)=1 from public.memberships where user_id=(select trusted_id from join_probe)),'app membership preserved');
select pg_temp.check(not exists(select 1 from public.memberships where user_id=(select parent_id from join_probe)),'no app role created by market join');
select pg_temp.check(not exists(select 1 from public.player_guardians where user_id=(select parent_id from join_probe)),'no child link required or created');
select pg_temp.check((select count(*)=1 from private.exchange_member_teams where user_id=(select parent_id from join_probe)),'repeat team selection deduplicated');
select set_config('request.jwt.claim.sub',admin_id::text,true) from join_probe;
set local role authenticated;
select pg_temp.check(public.exchange_restore(c,parent_id) and public.exchange_restore(c,trusted_id),'admin can restore') from join_probe;
select pg_temp.check(not public.exchange_restore(c,outsider_id),'restore cannot enroll outsider') from join_probe;
select public.exchange_invitation(c,true) from join_probe;
select set_config('request.jwt.claim.sub',outsider_id::text,true) from join_probe;
do $$begin begin perform public.exchange_join(c,(select token from join_token),true,array[team]) from join_probe;raise exception 'OLD TOKEN ACCEPTED';exception when raise_exception then if sqlerrm='OLD TOKEN ACCEPTED' then raise;end if;end;end $$;
select set_config('request.jwt.claim.sub',parent_id::text,true) from join_probe;
select pg_temp.check(public.exchange_access(c),'restored parent still member after link rotation') from join_probe;
reset role;
rollback;
select 'PASS: self-selected teams, club isolation, consent, confirmed email, admin-only list/suspend/restore, blocked repeat join, existing app membership preserved, no child/app assignments, old link rejected' result;
